beispiel-code:
public class Etikett {

    public static void main(String[] args) {
        // Kopfzeile mit Tabulator ausrichten
        System.out.println("Artikel\tPreis");
        System.out.println("Brot\t2.49");

        // print bleibt in der Zeile, println beendet sie
        System.out.print("Gesamt: ");
        System.out.println("2.49 Euro");

        /* Mehrzeiliger Kommentar:
           hier könnte man später
           Rabatte einbauen. */
        System.out.println("Danke für Ihren Einkauf!");
    }
}

